begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
insert into auth.users(id) values('b1000000-0000-4000-8000-000000000001'),('b1000000-0000-4000-8000-000000000002');
create function pg_temp.pr(n integer) returns uuid language sql as $$select ('b2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.pp(n integer) returns uuid language sql as $$select ('b3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.pu(n integer) returns uuid language sql as $$select ('b4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.path(n integer,r integer default 1) returns text language sql as $$select '50000000-0000-4000-8000-000000000002/chat/'||pg_temp.pr(r)::text||'/'||pg_temp.pp(n)::text||'/'||pg_temp.pu(n)::text||'.jpg'$$;
create function pg_temp.propose(n integer,r integer default 1,v integer default 0) returns public.design_change_proposals language sql as $$select public.propose_request_design(pg_temp.pp(n),pg_temp.pr(r),'Use this neckline and retain the original as history.',jsonb_build_array(pg_temp.pu(n)),(select version from public.tailoring_requests where id=pg_temp.pr(r)),v)$$;
create function pg_temp.fixture_upload(n integer,r integer default 1) returns void language plpgsql as $$begin perform public.reserve_chat_image(pg_temp.pu(n),pg_temp.pr(r),pg_temp.pp(n),'jpg');insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.path(n,r),'{"size":100,"mimetype":"image/jpeg"}');end;$$;
create function pg_temp.fail_proposal_alert() returns trigger language plpgsql as $$begin if new.kind like 'design_%' and current_setting('test.fail_proposal',true)='yes' then raise exception 'Injected proposal notification failure' using errcode='23514';end if;return new;end;$$;
create trigger fail_proposal_alert before insert on public.request_notifications for each row execute function pg_temp.fail_proposal_alert();
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.initialize_tailor_profile();
select public.save_tailor_profile('{"shop_name":"Proposal Atelier","description":"Bespoke garments for special occasions.","specialties":"Dresses","city":"Colombo","public_address":"123 Public Street","business_phone":"+94112223344","years_experience":5,"accepting_requests":true}',true,1);
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select public.save_customer_measurements('{"waist":80}',current_date);
select public.save_customer_design('b5000000-0000-4000-8000-000000000001','{"name":"Original dress","garment_type":"dress","colour":"ruby","neckline":"round","sleeve":"short","length":"midi"}',null);
select public.send_tailoring_request_with_measurements(pg_temp.pr(1),'50000000-0000-4000-8000-000000000002','dress','Please retain the original design snapshot.',1,current_date+30,true,'{"waist":80}',current_date,'b5000000-0000-4000-8000-000000000001',1);
do $$begin for i in 2..4 loop perform public.send_tailoring_request(pg_temp.pr(i),'50000000-0000-4000-8000-000000000002','dress','Request without an original design.',1,current_date+30);end loop;end;$$;
select pg_temp.expect_error('select pg_temp.propose(1)','42501');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
do $$begin for i in 1..3 loop perform public.decide_tailoring_request(pg_temp.pr(i),'accepted','',1);end loop;end;$$;
select public.send_request_quotation('b6000000-0000-4000-8000-000000000001',pg_temp.pr(1),2,'100.00','0.00','0.00','','Original price');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select public.answer_request_quotation('b6000000-0000-4000-8000-000000000001','accepted',1);
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.set_request_confirmed_date(pg_temp.pr(1),current_date+30,2);
select pg_temp.expect_error('select pg_temp.propose(4,4)','22023');
select public.reserve_chat_image(pg_temp.pu(1),pg_temp.pr(1),pg_temp.pp(1),'jpg');
select pg_temp.expect_error('select pg_temp.propose(1)','22023');
insert into storage.objects(bucket_id,name,metadata) values('request-chat-images',pg_temp.path(1),'{"size":100,"mimetype":"image/jpeg"}');
select pg_temp.expect_error($q$select public.propose_request_design(pg_temp.pp(1),pg_temp.pr(1),'','[]',2,0)$q$,'22023');
select pg_temp.expect_error($q$select public.propose_request_design(pg_temp.pp(1),pg_temp.pr(1),'Explain','["bad"]',2,0)$q$,'22023');
select pg_temp.expect_error($q$select public.propose_request_design(pg_temp.pp(1),pg_temp.pr(1),'Explain',jsonb_build_array(pg_temp.pu(1),pg_temp.pu(1)),2,0)$q$,'22023');
select pg_temp.expect_error($q$select public.propose_request_design(pg_temp.pp(1),pg_temp.pr(1),'Explain',jsonb_build_array(pg_temp.pu(1),pg_temp.pu(2),pg_temp.pu(3),pg_temp.pu(4)),2,0)$q$,'22023');
select pg_temp.expect_error($q$select public.propose_request_design(pg_temp.pp(1),pg_temp.pr(1),'Explain',jsonb_build_array(pg_temp.pu(1)),1,0)$q$,'40001');
select set_config('test.fail_proposal','yes',true);select pg_temp.expect_error('select pg_temp.propose(1)','23514');
select pg_temp.assert_true((select count(*)=0 from public.design_change_proposals),'submission failure rolls back proposal');
select pg_temp.assert_true((select count(*)=0 from public.request_agreed_designs),'submission failure rolls back baseline');
select pg_temp.assert_true((select proposal_id is null from public.chat_image_uploads where id=pg_temp.pu(1)),'submission failure keeps draft reusable');
select set_config('test.fail_proposal','no',true);select pg_temp.propose(1);select pg_temp.propose(1);
select pg_temp.assert_true((select count(*)=1 from public.design_change_proposals),'exact submission retries do not duplicate');
select pg_temp.assert_true((select original_snapshot->>'name'='Original dress' from public.request_agreed_designs where version=0),'original immutable snapshot copied as baseline');
select pg_temp.fixture_upload(2);select pg_temp.expect_error('select pg_temp.propose(2)','22023');
select public.advance_request_progress(pg_temp.pr(1),'confirmed','',3,false);
select public.advance_request_progress(pg_temp.pr(1),'ready','',4,false);
select pg_temp.expect_error($q$select public.complete_tailoring_request(pg_temp.pr(1),5,'Work ready',true)$q$,'22023');
select pg_temp.assert_true((select completed_at is null and version=5 from public.tailoring_requests where id=pg_temp.pr(1)),'pending proposal blocks actual completion RPC atomically');
select public.propose_request_design(pg_temp.pp(1),pg_temp.pr(1),'Use this neckline and retain the original as history.',jsonb_build_array(pg_temp.pu(1)),3,0);
select pg_temp.expect_error($q$select public.send_request_image_message(pg_temp.pp(1),pg_temp.pr(1),'Ordinary chat cannot consume a proposal file',jsonb_build_array(pg_temp.pu(1)))$q$,'22023');
select pg_temp.assert_true((select count(*)=0 from public.request_messages),'failed ordinary chat insertion rolls back');
delete from storage.objects where bucket_id='request-chat-images' and name=pg_temp.path(1);
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-chat-images' and name=pg_temp.path(1)),'pending proposal files protected from cleanup');
select pg_temp.assert_true((select count(*)=0 from public.unused_chat_images()),'proposal files never listed for cleanup');
select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(1),'accepted',1,true)$q$,'42501');
reset role;
select pg_temp.expect_error('update public.tailoring_requests set completed_at=now() where id=pg_temp.pr(1)','22023');
set local role authenticated;
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.design_change_proposals),'unrelated customer cannot read proposals');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-chat-images'),'unrelated customer cannot read proposal images');
select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(1),'accepted',1,true)$q$,'42501');
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-chat-images'),'customer sees submitted reference, not tailor draft');
select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(1),'withdrawn',1,false)$q$,'42501');
select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(1),'accepted',1,false)$q$,'22023');
select set_config('test.fail_proposal','yes',true);select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(1),'accepted',1,true)$q$,'23514');
select pg_temp.assert_true((select status='pending' from public.design_change_proposals where id=pg_temp.pp(1)),'acceptance failure rolls back decision');
select pg_temp.assert_true((select count(*)=1 from public.request_agreed_designs),'acceptance failure rolls back new design version');
select set_config('test.fail_proposal','no',true);
do $$declare before_row jsonb;begin select to_jsonb(r) into before_row from public.tailoring_requests r where id=pg_temp.pr(1);perform public.decide_request_design(pg_temp.pp(1),'accepted',1,true);perform pg_temp.assert_true((before_row-'design_change_revision')=(select to_jsonb(r)-'design_change_revision' from public.tailoring_requests r where id=pg_temp.pr(1)),'design acceptance never changes price, dates, stage or request version');end;$$;
select public.decide_request_design(pg_temp.pp(1),'accepted',1,true);
select pg_temp.assert_true((select count(*)=2 and max(version)=1 from public.request_agreed_designs),'one new immutable agreed version after retries');
select pg_temp.assert_true((select name='Original dress' from public.request_design_snapshots where request_id=pg_temp.pr(1)),'original design snapshot remains unchanged');
select pg_temp.assert_true((select values_cm='{"waist":80}'::jsonb from public.request_measurement_snapshots where request_id=pg_temp.pr(1)),'measurement snapshot unchanged');
select pg_temp.assert_true((select total=100 and notes='Original price' from public.request_quote_agreements where request_id=pg_temp.pr(1)),'agreed quotation unchanged by design acceptance');
select pg_temp.assert_true((select confirmed_date=current_date+30 from public.tailoring_requests where id=pg_temp.pr(1)),'confirmed deadline unchanged by design acceptance');
select pg_temp.expect_error('update public.request_agreed_designs set explanation=''changed''','42501');
select pg_temp.expect_error('delete from public.design_change_proposals','42501');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
-- Acceptance wins: a competing withdrawal cannot reverse it.
select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(1),'withdrawn',1,false)$q$,'40001');
select pg_temp.propose(2,1,1);
select public.decide_request_design(pg_temp.pp(2),'withdrawn',1,false);
select public.decide_request_design(pg_temp.pp(2),'withdrawn',1,false);
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
-- Withdrawal wins: a competing acceptance cannot create a design version.
select pg_temp.expect_error($q$select public.decide_request_design(pg_temp.pp(2),'accepted',1,true)$q$,'40001');
select pg_temp.assert_true((select count(*)=2 from public.request_agreed_designs where request_id=pg_temp.pr(1)),'withdrawal leaves agreed design unchanged');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.fixture_upload(5);select pg_temp.propose(5,1,1);
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select public.decide_request_design(pg_temp.pp(5),'accepted',1,true);
select pg_temp.assert_true((select array_agg(version order by version)=array[0,1,2] from public.request_agreed_designs where request_id=pg_temp.pr(1)),'successive accepted changes retain every agreed version');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.fixture_upload(3,2);select pg_temp.propose(3,2);
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select public.decide_request_design(pg_temp.pp(3),'declined',1,false);
select public.decide_request_design(pg_temp.pp(3),'declined',1,false);
select pg_temp.assert_true((select count(*)=1 and bool_and(original_snapshot is null) from public.request_agreed_designs where request_id=pg_temp.pr(2)),'legacy no-original baseline is valid');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.fixture_upload(4,2);select pg_temp.propose(4,2);
select set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
select public.decide_request_design(pg_temp.pp(4),'accepted',1,true);
select pg_temp.assert_true((select max(version)=1 from public.request_agreed_designs where request_id=pg_temp.pr(2)),'request without original can accept reference design');
reset role;
update public.tailoring_requests set completed_at=now() where id in(pg_temp.pr(1),pg_temp.pr(2));
set local role authenticated;
select public.decide_request_design(pg_temp.pp(4),'accepted',1,true);
select pg_temp.assert_true((select count(*)=5 from public.design_change_proposals),'complete proposal history retained after completion');
select pg_temp.assert_true((select count(*)=5 from storage.objects where bucket_id='request-chat-images'),'all submitted proposal references remain readable');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.propose(4,2);
select pg_temp.expect_error('select pg_temp.propose(6,2,1)','22023');
delete from storage.objects where bucket_id='request-chat-images';
select pg_temp.assert_true((select count(*)=5 from storage.objects where bucket_id='request-chat-images'),'tailor cannot delete submitted files after decisions');
select pg_temp.assert_true((select count(*)=4 from public.request_notifications where kind in('design_accepted','design_declined')),'tailor notification recipient count is deduplicated');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from public.request_agreed_designs),'unrelated admin cannot access agreed design history');
reset role;set local role anon;
select pg_temp.expect_error('select * from public.design_change_proposals','42501');
reset role;rollback;
select 'PASS: proposal roles, transitions, both race winners, immutable design history, no-original requests, rollback, notification retry and completion blocking' as result;
